PROVIDERS = {'اسنپ': {'URL': 'https://app.snapp.taxi/ride-history', 'EXTRACT': "() => {\n  const visible = e => e.getClientRects().length > 0;\n  const money = /(?:تومان|ریال)/;\n  const leaves = [...document.querySelectorAll('body *')].filter(e =>\n    visible(e) && money.test(e.innerText || '') &&\n    ![...e.children].some(c => money.test(c.innerText || '')));\n  const out = [];\n  for (const leaf of leaves) {\n    let best = leaf;\n    for (let p = leaf.parentElement; p && p !== document.body; p = p.parentElement) {\n      const t = p.innerText || '';\n      if (leaves.filter(x => p.contains(x)).length !== 1 || t.length > 6000) break;\n      best = p;\n    }\n    const text = (best.innerText || '').trim();\n    if (text.length < 25) continue;\n    const link = best.matches('a[href]') ? best : best.querySelector('a[href]');\n    out.push({text, price_text: leaf.innerText || '', link: link ? link.href : ''});\n  }\n  return out;\n}", 'SCROLL': "() => {\n  const all = [document.scrollingElement, ...document.querySelectorAll('body *')];\n  const targets = [...new Set(all)].filter(e => e && e.getClientRects().length &&\n    e.clientHeight > 100 && e.scrollHeight > e.clientHeight + 5 &&\n    (e === document.scrollingElement || /auto|scroll/.test(getComputedStyle(e).overflowY)));\n  let moved = false;\n  for (const e of targets) {\n    const before = e.scrollTop;\n    e.scrollBy(0, Math.max(300, e.clientHeight * .9));\n    if (Math.abs(e.scrollTop - before) > 1) moved = true;\n  }\n  const bottom = targets.every(e => e.scrollTop + e.clientHeight >= e.scrollHeight - 5);\n  return {moved, bottom, targets: targets.length};\n}"}, 'تپسی': {'URL': 'https://app.tapsi.cab/', 'EXTRACT': "() => {\n  const visible = e => e.getClientRects().length > 0;\n  const money = /(?:تومان|ریال)/;\n  const cancelled = /(?:لغو[\\s\\u200c]*شده|سفر[\\s\\u200c]*لغو|کنسل[\\s\\u200c]*شده)/;\n  const marker = s => money.test(s) || cancelled.test(s);\n  const leaves = [...document.querySelectorAll('body *')].filter(e =>\n    visible(e) && marker(e.innerText || '') &&\n    ![...e.children].some(c => marker(c.innerText || '')));\n  const out = [];\n  for (const leaf of leaves) {\n    let best = leaf;\n    for (let p = leaf.parentElement; p && p !== document.body; p = p.parentElement) {\n      const t = p.innerText || '';\n      if (leaves.filter(x => p.contains(x)).length !== 1 || t.length > 6000) break;\n      best = p;\n    }\n    const text = (best.innerText || '').trim();\n    if (text.length < 25) continue;\n    if (out.some(item => item.text === text)) continue;\n    const link = best.matches('a[href]') ? best : best.querySelector('a[href]');\n    out.push({text, price_text: leaf.innerText || '', link: link ? link.href : ''});\n  }\n  return out;\n}", 'SCROLL': "() => {\n  const all = [document.scrollingElement, ...document.querySelectorAll('body *')];\n  const targets = [...new Set(all)].filter(e => e && e.getClientRects().length &&\n    e.clientHeight > 100 && e.scrollHeight > e.clientHeight + 5 &&\n    (e === document.scrollingElement || /auto|scroll/.test(getComputedStyle(e).overflowY)));\n  let moved = false;\n  for (const e of targets) {\n    const before = e.scrollTop;\n    e.scrollBy(0, Math.max(300, e.clientHeight * .9));\n    if (Math.abs(e.scrollTop - before) > 1) moved = true;\n  }\n  const bottom = targets.every(e => e.scrollTop + e.clientHeight >= e.scrollHeight - 5);\n  return {moved, bottom, targets: targets.length};\n}"}}
